import static org.junit.Assert.*;
import static org.junit.Assert.assertNotNull;

@RunWith(JUnit4.class)
public class Compiler_initOptions_TriageGen1Test {

  private Compiler compiler;
  private CompilerOptions options;

  @Before
  public void setUp() {
    compiler = new Compiler();
    options = new CompilerOptions();
  }

  @Test
  public void testInitOptions_DefaultErrorManager() {
    compiler.initOptions(options);
    assertNotNull(compiler.getErrorManager());
    // Should be LoggerErrorManager by default if outStream is null
  }

  @Test
  public void testInitOptions_WithPrintStreamErrorManager() {
    // To trigger the 'else' branch where outStream != null, 
    // we need to use a constructor or internal state that sets outStream.
    // Since outStream is private, we use the constructor that accepts a PrintStream.
    PrintStream ps = new PrintStream(new java.io.ByteArrayOutputStream());
    Compiler compilerWithStream = new Compiler(ps);

    options.summaryDetailLevel = CheckLevel.ERROR;
    compilerWithStream.initOptions(options);

    assertNotNull(compilerWithStream.getErrorManager());
  }

  @Test
  public void testInitOptions_DiagnosticGroupsOverrideCheckTypes_Enable() {
    options.enables(DiagnosticGroups.CHECK_TYPES);
    compiler.initOptions(options);
    assertThat(options.checkTypes).isTrue();
  }

  @Test
  public void testInitOptions_DiagnosticGroupsOverrideCheckTypes_Disable() {
    options.disables(DiagnosticGroups.CHECK_TYPES);
    compiler.initOptions(options);
    assertThat(options.checkTypes).isFalse();
  }

  @Test
  public void testInitOptions_CheckTypesNotOverridden_AndFalse() {
    // Case: !options.checkTypes is true (meaning checkTypes is false)
    // and DiagnosticGroups did not override it.
    options.checkTypes = false;
    // We ensure no override by not calling enables/disables for CHECK_TYPES
    compiler.initOptions(options);

    // The code sets warning level for TYPE_PARSE_ERROR to OFF
    assertThat(options.getWarningLevel(RhinoErrorReporter.TYPE_PARSE_ERROR)).isEqualTo(CheckLevel.OFF);
  }

  @Test
  public void testInitOptions_CheckGlobalThisLevel_On() {
    options.checkGlobalThisLevel = CheckLevel.ERROR;
    compiler.initOptions(options);
    assertThat(options.getWarningLevel(DiagnosticGroups.GLOBAL_THIS)).isEqualTo(CheckLevel.ERROR);
  }

  @Test
  public void testInitOptions_CheckGlobalThisLevel_Off() {
    options.checkGlobalThisLevel = CheckLevel.OFF;
    compiler.initOptions(options);
    assertThat(options.getWarningLevel(DiagnosticGroups.GLOBAL_THIS)).isEqualTo(CheckLevel.OFF);
  }

  @Test
  public void testInitOptions_EcmaScript5Strict() {
    options.setLanguageIn(LanguageMode.ECMASCRIPT5_STRICT);
    compiler.initOptions(options);
    assertThat(options.getWarningLevel(DiagnosticGroups.ES5_STRICT)).isEqualTo(CheckLevel.ERROR);
  }

  @Test
  public void testInitOptions_NotEcmaScript5Strict() {
    options.setLanguageIn(LanguageMode.ECMASCRIPT6);
    compiler.initOptions(options);
    // Level shouldn't be forced to ERROR
  }

  @Test
  public void testInitOptions_VariableCheckGuard_AddedWhenDisabled() {
    options.checkSymbols = false;
    // By default, composedGuards.enables(CHECK_VARIABLES) will be true unless 
    // we modify the guard setup. However, we want to test the branch:
    // if (!options.checkSymbols && !composedGuards.enables(DiagnosticGroups.CHECK_VARIABLES))

    // To trigger the branch where the guard is added, we need composedGuards to NOT enable it.
    // Since SuppressDocWarningsGuard and options.getWarningsGuard() are added,
    // we can influence this via the options guard.
    options.setWarningsGuard(new ComposeWarningsGuard(Lists.newArrayList())); 
    // Note: This is tricky because the method creates a new ComposeWarningsGuard internally.
    // However, we can test the logic flow.

    compiler.initOptions(options);
    // If checkSymbols is false, the logic attempts to add a guard.
  }

  @Test
  public void testInitOptions_VariableCheckGuard_NotAddedWhenEnabled() {
    options.checkSymbols = true;
    compiler.initOptions(options);
    // If checkSymbols is true, the branch is skipped.
  }

  @Test
  public void testInitOptions_PreserveExistingErrorManager() {
    ErrorManager existingManager = new LoggerErrorManager(new com.google.javascript.jscomp.MessageFormatter(), null);
    compiler.setErrorManager(existingManager);

    compiler.initOptions(options);
    assertThat(compiler.getErrorManager()).isEqualTo(existingManager);
  }
}
